inline const VillagerFrame* getVillagerSprite(const std::string& name) {
    if (name == "idle_sw") return &VillagerAssets::FRAME_IDLE_SW;
    if (name == "idle_se") return &VillagerAssets::FRAME_IDLE_SE;
    if (name == "idle_ne") return &VillagerAssets::FRAME_IDLE_NE;
    if (name == "idle_nw") return &VillagerAssets::FRAME_IDLE_NW;
    if (name == "walk_sw") return &VillagerAssets::FRAME_WALK_SW;
    if (name == "walk_se") return &VillagerAssets::FRAME_WALK_SE;
    if (name == "walk_ne") return &VillagerAssets::FRAME_WALK_NE;
    if (name == "walk_nw") return &VillagerAssets::FRAME_WALK_NW;
    if (name == "pray_sw") return &VillagerAssets::FRAME_PRAY_SW;
    if (name == "pray_se") return &VillagerAssets::FRAME_PRAY_SE;
    if (name == "pray_ne") return &VillagerAssets::FRAME_PRAY_NE;
    if (name == "pray_nw") return &VillagerAssets::FRAME_PRAY_NW;
    if (name == "chop_sw") return &VillagerAssets::FRAME_CHOP_SW;
    if (name == "chop_se") return &VillagerAssets::FRAME_CHOP_SE;
    if (name == "carry_sw") return &VillagerAssets::FRAME_CARRY_SW;
    if (name == "carry_se") return &VillagerAssets::FRAME_CARRY_SE;
    if (name == "greet_sw") return &VillagerAssets::FRAME_GREET_SW;
    return &VillagerAssets::FRAME_IDLE_SW;
}

